const WebSocket = require('ws');
const DDPClient = require('ddp');

const ddpclient = new DDPClient({
  host: "web.chal.csaw.io",
  port: 5000,
  use_ssl: false
});

console.log("[+] Attempting to connect to DDP endpoint...");

ddpclient.connect((error, wasReconnect) => {
  if (error) {
    console.log("[-] Error connecting:", error);
    return;
  }

  console.log("[+] Connected to DDP endpoint!");

  // Try to list methods
  ddpclient.call("methods", [], (err, result) => {
    if (err) {
      console.log("[-] Error listing methods:", err);
    } else {
      console.log("[+] Available methods:", result);
    }
  });

  // Try to list collections
  console.log("[+] Attempting to subscribe to known collections...");

  // Try users collection
  ddpclient.subscribe('meteor.users', [], (err) => {
    if (err) {
      console.log("[-] Error subscribing to users:", err);
    } else {
      console.log("[+] Subscribed to users collection");

      // Try to query users
      ddpclient.call('users.find', [], (err, result) => {
        if (err) {
          console.log("[-] Error querying users:", err);
        } else {
          console.log("[+] Users query result:", result);
        }
      });
    }
  });

  // Try notes collection
  ddpclient.subscribe('notes', [], (err) => {
    if (err) {
      console.log("[-] Error subscribing to notes:", err);
    } else {
      console.log("[+] Subscribed to notes collection");

      // Try to query notes
      ddpclient.call('notes.find', [], (err, result) => {
        if (err) {
          console.log("[-] Error querying notes:", err);
        } else {
          console.log("[+] Notes query result:", result);
        }
      });
    }
  });

  // Try to directly call some common Meteor methods
  ddpclient.call('listCollections', [], (err, result) => {
    if (err) {
      console.log("[-] Error listing collections:", err);
    } else {
      console.log("[+] Collections:", result);
    }
  });

  // Set up collection observers
  ddpclient.observe("users", {
    added: function(id, fields) {
      console.log("[+] User added:", id, fields);
    },
    changed: function(id, fields) {
      console.log("[+] User changed:", id, fields);
    },
    removed: function(id) {
      console.log("[+] User removed:", id);
    }
  });

  ddpclient.observe("notes", {
    added: function(id, fields) {
      console.log("[+] Note added:", id, fields);
    },
    changed: function(id, fields) {
      console.log("[+] Note changed:", id, fields);
    },
    removed: function(id) {
      console.log("[+] Note removed:", id);
    }
  });
});

// Keep the script running for a while to collect responses
setTimeout(() => {
  console.log("[+] Closing connection...");
  ddpclient.close();
  process.exit(0);
}, 10000);

