import websocket
import json
import time
import threading
import ssl

def on_message(ws, message):
    try:
        msg = json.loads(message)
        # Look for any data containing Terry
        if isinstance(msg, dict):
            msg_str = json.dumps(msg).lower()
            if 'terry' in msg_str:
                print(f"Found Terry reference: {message}")

        # Handle different message types
        if 'msg' in msg:
            if msg['msg'] == 'added' and 'collection' in msg:
                if msg['collection'] == 'notes':
                    print(f"Note found: {message}")
                elif msg['collection'] == 'users':
                    print(f"User found: {message}")
    except Exception as e:
        print(f"Error processing message: {e}")

def on_error(ws, error):
    print(f"Error: {error}")

def on_close(ws, close_status_code, close_msg):
    print("Connection closed")

def on_open(ws):
    print("Connection opened")

    # Initial connect
    connect_msg = {
        "msg": "connect",
        "version": "1",
        "support": ["1"]
    }
    ws.send(json.dumps(connect_msg))

    # Try different subscriptions
    subscriptions = [
        "notes",
        "users",
        "allNotes",
        "publicNotes",
        "userNotes",
        "terry_notes"
    ]

    for i, sub in enumerate(subscriptions):
        sub_msg = {
            "msg": "sub",
            "name": sub,
            "params": [],
            "id": str(i + 1)
        }
        print(f"Trying subscription: {sub}")
        ws.send(json.dumps(sub_msg))
        time.sleep(1)

    # Try to query for Terry's data
    method_calls = [
        {
            "msg": "method",
            "method": "getNotes",
            "params": [],
            "id": "m1"
        },
        {
            "msg": "method",
