  'notescount': function () {
    return Template.instance().notescount.get();
  }
});
Template.Layout_login.events({
  'click #btn-login': function (e, t) {
    var email = t.find('#email').value;
    var password = t.find('#password').value;

    if (!email || !password) {
      Materialize.toast({
        html: "Email and password required!",
        displayLength: 3000
      });
    } else {
      Meteor.loginWithPassword({
        username: email
      }, password, function (err, res) {
        if (err) {
          Materialize.toast({
            html: "Login failed!",
            displayLength: 3000
          });
        } else {
          FlowRouter.go('/');
        }
      });
    }
  },
  'click #btn-signup': function (e, t) {
    var email = t.find('#signup-email').value;
    var password = t.find('#signup-password').value;
    var passwordConfirm = t.find('#signup-password-confirm').value;

    if (password == passwordConfirm) {
      Accounts.createUser({
        username: email,
        password: password
      }, function (err, res) {
        if (err) {
          Materialize.toast({
            html: "Sign up failed!",
            displayLength: 3000
          });
          return;
        }

        Materialize.toast({
          html: "Registered!",
          displayLength: 3000
        });
        Meteor.loginWithPassword({
          username: email
        }, password, function (err, res) {
          if (err) {
            Materialize.toast({
              html: "Login failed!",
              displayLength: 3000
            });
            return;
          } else {
            FlowRouter.go('/');
          }
        });
      });
    } else {
      Materialize.toast({
        html: "Passwords do not match!",
        displayLength: 3000
      });
    }
  }
});
