var Meteor;
module.link("meteor/meteor", {
  Meteor: function (v) {
    Meteor = v;
  }
}, 0);
var Accounts;
module.link("meteor/accounts-base", {
  Accounts: function (v) {
    Accounts = v;
  }
}, 1);
var ReactiveVar;
module.link("meteor/reactive-var", {
  ReactiveVar: function (v) {
    ReactiveVar = v;
  }
}, 2);
module.link("./login.html");
var Materialize;
module.link("materialize-css", {
  "default": function (v) {
    Materialize = v;
  }
}, 3);
var $;
module.link("jquery", {
  "default": function (v) {
    $ = v;
  }
}, 4);
Template.Layout_login.onCreated(function () {
  var self = this;
  this.notescount = new ReactiveVar(0);

  function noteCountUpdater() {
    Meteor.call('notes.count', {
      body: {
        $ne: ''
      }
    }, function (err, res) {
      //console.log(res)
      self.notescount.set(res);
    });
  }

  noteCountUpdater();
  this.refresher = Meteor.setInterval(noteCountUpdater, 1000);
});
Template.Layout_login.onDestroyed(function () {
  Meteor.clearInterval(this.refresher);
});
Template.Layout_login.onRendered(function () {
  $('.tabs').tabs();
});
Template.Layout_login.helpers({
  'notescount': function () {
    return Template.instance().notescount.get();
  }
});
Template.Layout_login.events({
  'click #btn-login': function (e, t) {
    var email = t.find('#email').value;
    var password = t.find('#password').value;

    if (!email || !password) {
      Materialize.toast({
        html: "Email and password required!",
        displayLength: 3000
      });
    } else {
      Meteor.loginWithPassword({
        username: email
      }, password, function (err, res) {
        if (err) {
          Materialize.toast({
            html: "Login failed!",
            displayLength: 3000
          });
        } else {
          FlowRouter.go('/');
        }
      });
    }
  },
  'click #btn-signup': function (e, t) {
    var email = t.find('#signup-email').value;
    var password = t.find('#signup-password').value;
    var passwordConfirm = t.find('#signup-password-confirm').value;

    if (password == passwordConfirm) {
      Accounts.createUser({
        username: email,
        password: password
      }, function (err, res) {
        if (err) {
          Materialize.toast({
            html: "Sign up failed!",
            displayLength: 3000
          });
          return;
        }

        Materialize.toast({
          html: "Registered!",
          displayLength: 3000
        });
        Meteor.loginWithPassword({
          username: email
        }, password, function (err, res) {
          if (err) {
            Materialize.toast({
              html: "Login failed!",
              displayLength: 3000
            });
            return;
          } else {
            FlowRouter.go('/');
          }
        });
      });
    } else {
      Materialize.toast({
        html: "Passwords do not match!",
        displayLength: 3000
      });
    }
  }
});
